use anyhow :: { Context , Result } ; use rayon :: prelude :: * ; use std :: fs ; use std :: sync :: Arc ; use std :: sync :: Mutex ; use crate :: context :: AppContext ; use crate :: actions :: RepoAction ; use crate :: rollup_lock :: RollupLock ; use crate :: zkperf_integration :: ZkperfIntegrator ; use super :: * ; use std :: path :: PathBuf ; use tempfile :: tempdir ; # [doc = " Apply zkperf annotations to a vendored repository"] fn apply_zkperf_annotations (repo_path : & std :: path :: Path , ctx : & AppContext) -> Result < () > { let zkperf_enabled = std :: env :: var ("CARGO_VENDORMOD_ZKPERF") . unwrap_or_else (| _ | "false" . to_string ()) == "true" ; if ! zkperf_enabled { println ! ("Zkperf integration disabled. Set CARGO_VENDORMOD_ZKPERF=true to enable.") ; return Ok (()) ; } println ! ("Applying zkperf annotations to {}..." , repo_path . display ()) ; let zkperf_tool_path = std :: path :: PathBuf :: from ("zkperf/cargo-zkperf/target/release/cargo-zkperf") ; let integrator = ZkperfIntegrator :: new (Some (zkperf_tool_path) , false) ; integrator . apply_zkperf_annotations (repo_path) ? ; println ! ("Zkperf annotations applied to {}" , repo_path . display ()) ; Ok (()) }